{
  "action": "query",
  "q": {
    "select": ["component.product_number"],
    "from": "bill_of_materials AS bom",
    "join": [
      {
        "type": "inner",
        "table": "product AS assembly",
        "on": "bom.assembly_id = assembly.product_id"
      },
      {
        "type": "inner",
        "table": "product AS component",
        "on": "bom.component_id = component.product_id"
      }
    ],
    "where": [
      "assembly.product_number = 'HB-R956'",
      "bom.bom_level = 1",
      "bom.start_date <= DATE '2025-06-30'",
      "(bom.end_date IS NULL OR bom.end_date >= DATE '2025-06-30')"
    ]
  }
}

